import{_ as a,o as t,c as r,a0 as s}from"./chunks/framework.BTg7EidG.js";const i="/athanor-docs/screens/city-jobs.png",n="/athanor-docs/screens/city-training.png",o="/athanor-docs/screens/city-build.png",l="/athanor-docs/screens/city-research.png",f=JSON.parse('{"title":"Cities & Holdings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cities.md","filePath":"guide/cities.md"}'),d={name:"guide/cities.md"};function h(c,e,g,p,u,m){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="cities-holdings" tabindex="-1">Cities &amp; Holdings <a class="header-anchor" href="#cities-holdings" aria-label="Permalink to &quot;Cities &amp; Holdings&quot;">​</a></h1><p>Tap one of your cities (or press <strong>Manage City</strong> from the hero panel) to open the city board. Cities level from 1 to 3 — each level adds job slots, a floor to the skyline, and eventually unlocks the best projects.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p><img src="'+i+'" alt="City jobs"></p><p>Spare <strong>Followers</strong> work the four city jobs, each producing one unit a day: the <strong>Market</strong> (gold), <strong>Tavern</strong> (elixir), <strong>Temple</strong> (reagents) and <strong>Magistrate</strong> (infamy). Infamy matters: your deeds plus your magistrates decide how many new Followers arrive every seventh day.</p><h2 id="training" tabindex="-1">Training <a class="header-anchor" href="#training" aria-label="Permalink to &quot;Training&quot;">​</a></h2><p><img src="'+n+'" alt="The training hall"></p><p>Every unit standing at the building — in a party or the garrison — can buy its next level for gold and elixir. Training takes the day; the queue shows who&#39;s drilling. Keep a high-level veteran garrisoned and new recruits start at half their level.</p><p>Barracks train warriors, Laboratories train alchemists, Shadow Guilds train rogues; cities and Grand Athanors drill warriors. Tap any owned trainer building on the map to open its hall directly.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p><img src="'+o+'" alt="The build queue"></p><p>Cities can raise new structures on free land beside them — a Barracks, Laboratory or Distillery, and at city level 3 a Shadow Guild. One project at a time; a few days each.</p><h2 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h2><p><img src="'+l+'" alt="Skill research"></p><p>The Town Hall researches hero skills, one project at a time, guild-wide once learned. Class skills are innate; a <strong>level‑2 city</strong> unlocks tier two (<em>Shield Wall</em>, <em>Field Mending</em>) and a <strong>level‑3 city</strong> unlocks tier three (<em>Overwhelm</em>). Once researched, assign the skill on any matching hero&#39;s sheet.</p><h2 id="defense" tabindex="-1">Defense <a class="header-anchor" href="#defense" aria-label="Permalink to &quot;Defense&quot;">​</a></h2><p>If a visible enemy prowls within sight of an undefended holding, the game warns you and offers an <strong>emergency muster</strong> — recruits or mercenaries straight onto the walls. The locate button&#39;s jump list shows every city, flagging any whose walls stand empty.</p>',17)])])}const b=a(d,[["render",h]]);export{f as __pageData,b as default};
